<form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Title</label><input required name="title" value="<?=e($book['title']??'')?>"><div class="form-grid"><div><label>ISBN</label><input required name="isbn" value="<?=e($book['isbn']??'')?>"></div><div><label>Publication year</label><input required type="number" name="publication_year" value="<?=e((string)($book['publication_year']??date('Y')))?>"></div><div><label>Pages</label><input required type="number" name="pages" value="<?=e((string)($book['pages']??1))?>"></div><div><label>Language</label><input required name="language" value="<?=e($book['language']??'English')?>"></div></div><?php foreach(['authors'=>'Author','publishers'=>'Publisher','categories'=>'Category'] as $key=>$label): $field=['authors'=>'author_id','publishers'=>'publisher_id','categories'=>'category_id'][$key];?><label><?=$label?></label><select required name="<?=$field?>"><?php foreach($lists[$key] as $x):?><option value="<?=$x['id']?>" <?=($book[$field]??0)==$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select><?php endforeach;?><label>Description</label><textarea name="description"><?=e($book['description']??'')?></textarea><p><button>Save book</button></p></form>
